<?php
declare(strict_types=1);
namespace DigiForge\Portal;
use DigiForge\POD\{PersonalizedProofRepository,Shop2ProductWorkflow};
/** Existing Shop 2 portal extension; no REST registration or transport. */
final class PersonalizedPreparationPanel {
 private static bool $registered=false;
 public const ACTION='digiforge_personalized_preparation';
 public function register():void{if(self::$registered)return;self::$registered=true;add_action('admin_post_'.self::ACTION,[$this,'submit']);add_filter('do_shortcode_tag',[$this,'render'],200,4);}
 public function process(array $p):array|\WP_Error {
  if(!Shop2ProductWorkflow::access(true)||($p['shop_key']??null)!=='personalized_pod'||!is_string($p['_wpnonce']??null)||!wp_verify_nonce($p['_wpnonce'],self::ACTION)||strlen((string)wp_json_encode($p))>6000000)return PersonalizedProofRepository::error('access_or_confirmation');
  $repo=new PersonalizedProofRepository();$op=$p['operation']??null;
  if($op==='prepare'){if(!is_string($p['workflow']??null)||!is_string($p['input_json']??null)||strlen($p['input_json'])>5500000)return PersonalizedProofRepository::error('input');try{$input=json_decode($p['input_json'],true,32,JSON_THROW_ON_ERROR);}catch(\Throwable){return PersonalizedProofRepository::error('json');}if(!is_array($input))return PersonalizedProofRepository::error('json');$parent=$p['parent']??null;if($parent==='')$parent=null;if($parent!==null&&!is_string($parent))return PersonalizedProofRepository::error('parent');return $repo->create($p['workflow'],$input,$parent);}
  if(!is_string($p['proof']??null))return PersonalizedProofRepository::error('proof');
  if($op==='personalize')return is_array($p['values']??null)?$repo->personalize($p['proof'],$p['values']):PersonalizedProofRepository::error('values');
  if($op==='review'){if(($p['confirm']??null)!=='LOCAL_PROOF_ONLY'||!is_string($p['decision']??null)||!is_string($p['note']??null))return PersonalizedProofRepository::error('review');$d=$repo->decide($p['proof'],$p['decision'],$p['note']);return is_wp_error($d)?$d:['hash'=>$p['proof']];}
  if($op==='provider_plan'){if(!is_string($p['integration_id']??null)||!preg_match('/^[1-9][0-9]{0,8}$/D',$p['integration_id'])||!is_string($p['order_line_reference']??null))return PersonalizedProofRepository::error('integration');$out=(new \DigiForge\POD\PersonalizedPrintifyPreparation())->plan($p['proof'],(int)$p['integration_id'],$p['order_line_reference'],is_string($p['package']??null)&&$p['package']!==''?$p['package']:null);return is_wp_error($out)?$out:['export'=>$out,'hash'=>$p['proof']];}
  if($op==='export'){if(!is_string($p['order_line_reference']??null))return PersonalizedProofRepository::error('order');$package=$p['package']??null;if($package==='')$package=null;if($package!==null&&!is_string($package))return PersonalizedProofRepository::error('package');$out=$repo->export($p['proof'],$p['order_line_reference'],$package);return is_wp_error($out)?$out:['export'=>$out,'hash'=>$p['proof']];}
  return PersonalizedProofRepository::error('operation');
 }
 public function submit():never {
  $r=($_SERVER['REQUEST_METHOD']??'')==='POST'?$this->process(wp_unslash($_POST)):PersonalizedProofRepository::error('method');nocache_headers();header('X-Content-Type-Options: nosniff');
  if(!is_wp_error($r)&&isset($r['export'])){header('Content-Type: application/json');header('Content-Disposition: attachment; filename="digiforge-held-personalized-preparation.json"');echo wp_json_encode($r['export'],JSON_PRETTY_PRINT);exit;}
  $q=['df_view'=>'pod_personalized','df_shop'=>'personalized_pod','df_preparation_result'=>is_wp_error($r)?'blocked':'recorded'];if(!is_wp_error($r))$q['df_proof']=$r['hash'];wp_safe_redirect(add_query_arg($q,home_url('/')));exit;
 }
 private function form(string $op,?string $hash=null):string {$h='<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field(self::ACTION,'_wpnonce',true,false);foreach(['action'=>self::ACTION,'operation'=>$op,'shop_key'=>'personalized_pod']+($hash===null?[]:['proof'=>$hash])as $k=>$v)$h.='<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';return $h;}
 public function render(string $html,string $tag,array $atts,array $match):string {
  if($tag!=='digiforge_admin_portal'||($_GET['df_shop']??null)!=='personalized_pod'||($_GET['df_view']??null)!=='pod_personalized'||!Shop2ProductWorkflow::access(true))return $html;
  $h='<section class="df-panel"><h2>Customer personalization and proof preparation</h2><p>Local review only. Import existing qualified fixed artwork and exact source/layer evidence; no artwork rebuild, Printify Save, product duplication or order submission. R4 artwork/rights/geometry remain external evidence requirements. Never enter credentials or payment/address data.</p>';
  if(isset($_GET['df_preparation_result']))$h.='<p role="status">'.(($_GET['df_preparation_result']==='recorded')?'Local record saved.':'Preparation blocked; verify exact source, scope and input contract.').'</p>';
  $h.=$this->form('prepare').'<label>Existing supplier workflow SHA-256<input name="workflow" pattern="[a-f0-9]{64}" required></label><label>Parent proof SHA-256 for correction (optional)<input name="parent"></label><label>Versioned template, fixed PNG and customer values JSON<textarea name="input_json" rows="12" required style="width:100%;max-width:100%;box-sizing:border-box"></textarea></label><button>Prepare local proof</button></form>';
  $repo=new PersonalizedProofRepository();$queue=$repo->queue();if(!is_wp_error($queue)){$h.='<h3>Proof review queue (latest 25)</h3><ul>';foreach($queue as $row)$h.='<li><a href="'.esc_url(add_query_arg(['df_view'=>'pod_personalized','df_shop'=>'personalized_pod','df_proof'=>$row['hash']],home_url('/'))).'">'.esc_html($row['fixture_id'].' template '.$row['template_version'].' — '.$row['review_state']).'</a></li>';$h.='</ul>';}else{$h.='<p role="alert">Proof review queue evidence unavailable; integrity review required.</p>';}
  $hash=$_GET['df_proof']??null;if(is_string($hash)){$r=$repo->read($hash);if(!is_wp_error($r)){$p=$r['prepared'];$h.='<h3>Exact local proof</h3><p>'.esc_html($hash).'</p><img style="max-width:100%;height:auto" alt="Local personalization proof, not supplier certification" src="data:image/svg+xml;base64,'.base64_encode($p['proof_svg']).'"><p>Preview typography and provider parity require review. Production references fixed artwork separately from native text to prevent double printing.</p><ul>';foreach($p['remaining_gates']as $gate)$h.='<li>'.esc_html($gate).'</li>';$h.='</ul>'.$this->form('personalize',$hash);$current=array_column($p['native_bindings'],'value','field');foreach($p['template_evidence']['fields']as $field){$h.='<label>'.esc_html($field['label']??$field['key']).'<input name="values['.esc_attr($field['key']).']" type="'.($field['type']==='date'?'date':'text').'" maxlength="'.(int)$field['max_length'].'" value="'.esc_attr($current[$field['key']]).'" required></label>';}$h.='<button>Create new customer proof version</button></form>'.$this->form('review',$hash).'<label>Decision<select name="decision"><option>REJECT</option><option>APPROVE</option></select></label><label>Review note<textarea name="note" maxlength="1000" required></textarea></label><label><input type="checkbox" name="confirm" value="LOCAL_PROOF_ONLY" required>Review this exact local proof only; no supplier certification or external authority.</label><button>Record immutable review</button></form>'.$this->form('export',$hash).'<label>Local order-line reference<input name="order_line_reference" maxlength="64" required></label><label>Existing approved listing package SHA-256 (optional)<input name="package"></label><button>Export held preparation</button></form>'.$this->form('provider_plan',$hash).'<label>Existing Shop 2 Printify integration ID<input name="integration_id" required inputmode="numeric"></label><label>Local order-line reference<input name="order_line_reference" maxlength="64" required></label><label>Approved listing package SHA-256 (optional)<input name="package"></label><button>Export readback and held provider preparation</button></form>';}}
  return $html.$h.'</section>';
 }
}
